package com.pms.inventory.inventory.service;

import com.pms.inventory.common.exception.InventoryException;
import com.pms.inventory.inventory.entity.RoomTypeInventoryDaily;
import com.pms.inventory.inventory.repository.RoomTypeInventoryDailyRepository;
import com.pms.inventory.reconciliation.dto.InventoryReconciliationRequest;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.function.Function;
import java.util.stream.Collectors;

@Service("inventoryReconciliationDomainService")
public class InventoryReconciliationService {

    private final RoomTypeInventoryDailyRepository dailyRepository;

    public InventoryReconciliationService(RoomTypeInventoryDailyRepository dailyRepository) {
        this.dailyRepository = dailyRepository;
    }

    @Transactional
    public int reconcile(InventoryReconciliationRequest request) {
        validateDateRange(request.fromDate(), request.toDate());

        int affected = 0;
        for (InventoryReconciliationRequest.RoomTypeInventoryInput roomTypeInput : request.roomTypes()) {
            affected += reconcileRoomType(
                    request.propertyId(),
                    roomTypeInput.roomTypeId(),
                    roomTypeInput.totalInventory(),
                    request.fromDate(),
                    request.toDate()
            );
        }
        return affected;
    }

    private int reconcileRoomType(
            UUID propertyId,
            UUID roomTypeId,
            int totalInventory,
            LocalDate fromDate,
            LocalDate toDate
    ) {
        Map<LocalDate, RoomTypeInventoryDaily> existingByDate = loadExistingByDate(propertyId, roomTypeId, fromDate, toDate);

        List<RoomTypeInventoryDaily> toSave = new ArrayList<>();
        LocalDateTime now = LocalDateTime.now();
        for (LocalDate date = fromDate; date.isBefore(toDate); date = date.plusDays(1)) {
            RoomTypeInventoryDaily row = existingByDate.get(date);
            row = (row == null)
                    ? newDailyRow(propertyId, roomTypeId, date, totalInventory, now)
                    : updateExistingRow(row, totalInventory, date, now);
            toSave.add(row);
        }

        dailyRepository.saveAll(toSave);
        return toSave.size();
    }

    private void validateDateRange(LocalDate fromDate, LocalDate toDate) {
        if (!toDate.isAfter(fromDate)) {
            throw new InventoryException("Invalid reconciliation date range");
        }
    }

    private Map<LocalDate, RoomTypeInventoryDaily> loadExistingByDate(
            UUID propertyId,
            UUID roomTypeId,
            LocalDate fromDate,
            LocalDate toDate
    ) {
        return dailyRepository.findForUpdate(propertyId, roomTypeId, fromDate, toDate)
                .stream()
                .collect(Collectors.toMap(
                        RoomTypeInventoryDaily::getBusinessDate,
                        Function.identity(),
                        (left, right) -> left,
                        HashMap::new
                ));
    }

    private RoomTypeInventoryDaily newDailyRow(
            UUID propertyId,
            UUID roomTypeId,
            LocalDate date,
            int totalInventory,
            LocalDateTime now
    ) {
        return RoomTypeInventoryDaily.builder()
                .propertyId(propertyId)
                .roomTypeId(roomTypeId)
                .businessDate(date)
                .totalInventory(totalInventory)
                .reservedCount(0)
                .blockedCount(0)
                .createdAt(now)
                .updatedAt(now)
                .build();
    }

    private RoomTypeInventoryDaily updateExistingRow(
            RoomTypeInventoryDaily row,
            int totalInventory,
            LocalDate date,
            LocalDateTime now
    ) {
        int minimumRequired = row.getReservedCount() + row.getBlockedCount();
        if (totalInventory < minimumRequired) {
            throw new InventoryException("Cannot reduce total inventory below reserved + blocked on " + date);
        }
        row.setTotalInventory(totalInventory);
        row.setUpdatedAt(now);
        return row;
    }
}

package com.pms.inventory.inventory.service;

import com.pms.inventory.common.exception.InventoryException;
import com.pms.inventory.inventory.entity.RoomTypeInventoryDaily;
import com.pms.inventory.inventory.repository.RoomTypeInventoryDailyRepository;
import com.pms.inventory.reconciliation.dto.InventoryReconciliationRequest;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.function.Function;
import java.util.stream.Collectors;

@Service("inventoryReconciliationDomainService")
public class InventoryReconciliationService {

    private final RoomTypeInventoryDailyRepository dailyRepository;

    public InventoryReconciliationService(RoomTypeInventoryDailyRepository dailyRepository) {
        this.dailyRepository = dailyRepository;
    }

    @Transactional
    public int reconcile(InventoryReconciliationRequest request) {
        validateDateRange(request.fromDate(), request.toDate());

        return request.roomTypes().stream()
                .mapToInt(roomTypeInput -> reconcileRoomType(
                        request.propertyId(),
                        roomTypeInput.roomTypeId(),
                        roomTypeInput.totalInventory(),
                        request.fromDate(),
                        request.toDate()
                ))
                .sum();
    }

    private int reconcileRoomType(
            UUID propertyId,
            UUID roomTypeId,
            int totalInventory,
            LocalDate fromDate,
            LocalDate toDate
    ) {
        Map<LocalDate, RoomTypeInventoryDaily> existingByDate = loadExistingByDate(propertyId, roomTypeId, fromDate, toDate);
        List<RoomTypeInventoryDaily> toSave = buildRowsToSave(
                propertyId,
                roomTypeId,
                totalInventory,
                fromDate,
                toDate,
                existingByDate
        );

        dailyRepository.saveAll(toSave);
        return toSave.size();
    }

    private List<RoomTypeInventoryDaily> buildRowsToSave(
            UUID propertyId,
            UUID roomTypeId,
            int totalInventory,
            LocalDate fromDate,
            LocalDate toDate,
            Map<LocalDate, RoomTypeInventoryDaily> existingByDate
    ) {
        List<RoomTypeInventoryDaily> toSave = new ArrayList<>();
        LocalDateTime now = LocalDateTime.now();
        for (LocalDate date = fromDate; date.isBefore(toDate); date = date.plusDays(1)) {
            toSave.add(upsertRowForDate(propertyId, roomTypeId, totalInventory, date, now, existingByDate));
        }
        return toSave;
    }

    private RoomTypeInventoryDaily upsertRowForDate(
            UUID propertyId,
            UUID roomTypeId,
            int totalInventory,
            LocalDate date,
            LocalDateTime now,
            Map<LocalDate, RoomTypeInventoryDaily> existingByDate
    ) {
        RoomTypeInventoryDaily existing = existingByDate.get(date);
        return (existing == null)
                ? newDailyRow(propertyId, roomTypeId, date, totalInventory, now)
                : updateExistingRow(existing, totalInventory, date, now);
    }

    private void validateDateRange(LocalDate fromDate, LocalDate toDate) {
        if (!toDate.isAfter(fromDate)) {
            throw new InventoryException("Invalid reconciliation date range");
        }
    }

    private Map<LocalDate, RoomTypeInventoryDaily> loadExistingByDate(
            UUID propertyId,
            UUID roomTypeId,
            LocalDate fromDate,
            LocalDate toDate
    ) {
        return dailyRepository.findForUpdate(propertyId, roomTypeId, fromDate, toDate)
                .stream()
                .collect(Collectors.toMap(
                        RoomTypeInventoryDaily::getBusinessDate,
                        Function.identity(),
                        (left, right) -> left,
                        HashMap::new
                ));
    }

    private RoomTypeInventoryDaily newDailyRow(
            UUID propertyId,
            UUID roomTypeId,
            LocalDate date,
            int totalInventory,
            LocalDateTime now
    ) {
        return RoomTypeInventoryDaily.builder()
                .propertyId(propertyId)
                .roomTypeId(roomTypeId)
                .businessDate(date)
                .totalInventory(totalInventory)
                .reservedCount(0)
                .blockedCount(0)
                .createdAt(now)
                .updatedAt(now)
                .build();
    }

    private RoomTypeInventoryDaily updateExistingRow(
            RoomTypeInventoryDaily row,
            int totalInventory,
            LocalDate date,
            LocalDateTime now
    ) {
        int minimumRequired = row.getReservedCount() + row.getBlockedCount();
        if (totalInventory < minimumRequired) {
            throw new InventoryException("Cannot reduce total inventory below reserved + blocked on " + date);
        }
        row.setTotalInventory(totalInventory);
        row.setUpdatedAt(now);
        return row;
    }
}

package com.pms.inventory.reconciliation.service;

import com.pms.inventory.inventory.entity.RoomTypeInventoryDaily;
import com.pms.inventory.inventory.repository.RoomTypeInventoryDailyRepository;
import com.pms.inventory.reconciliation.dto.InventoryReconciliationRequest;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.time.LocalDate;
import java.util.List;
import java.util.UUID;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.ArgumentMatchers.anyList;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class InventoryReconciliationServiceTest {

    @Mock
    private RoomTypeInventoryDailyRepository repository;

    @InjectMocks
    private com.pms.inventory.inventory.service.InventoryReconciliationService service;

    @Test
    void reconciliationCreatesDailyInventoryAndIsIdempotent() {
        UUID propertyId = UUID.randomUUID();
        UUID roomTypeId = UUID.randomUUID();
        InventoryReconciliationRequest request = new InventoryReconciliationRequest(
                propertyId,
                LocalDate.of(2026, 7, 20),
                LocalDate.of(2026, 7, 23),
                List.of(new InventoryReconciliationRequest.RoomTypeInventoryInput(roomTypeId, 3))
        );

        when(repository.findForUpdate(propertyId, roomTypeId, request.fromDate(), request.toDate()))
                .thenReturn(List.of())
                .thenReturn(List.of(
                        RoomTypeInventoryDaily.builder().propertyId(propertyId).roomTypeId(roomTypeId).businessDate(LocalDate.of(2026, 7, 20)).totalInventory(3).reservedCount(0).blockedCount(0).build(),
                        RoomTypeInventoryDaily.builder().propertyId(propertyId).roomTypeId(roomTypeId).businessDate(LocalDate.of(2026, 7, 21)).totalInventory(3).reservedCount(0).blockedCount(0).build(),
                        RoomTypeInventoryDaily.builder().propertyId(propertyId).roomTypeId(roomTypeId).businessDate(LocalDate.of(2026, 7, 22)).totalInventory(3).reservedCount(0).blockedCount(0).build()
                ));

        int firstAffected = service.reconcile(request);
        int secondAffected = service.reconcile(request);

        assertEquals(3, firstAffected);
        assertEquals(3, secondAffected);
        verify(repository).saveAll(anyList());
    }
}

