package com.pms.property.integration.inventory.service;

import com.pms.property.domain.room.entity.RoomOutletTypeEntity;
import com.pms.property.integration.inventory.dto.InventoryReconciliationRequest;
import com.pms.property.integration.inventory.dto.RoomMasterSyncRequest;
import com.pms.property.domain.room.entity.InventoryRoomEntity;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.UUID;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

@Component
public class InventorySyncPayloadMapper {

    private final int horizonDays;

    public InventorySyncPayloadMapper(@Value("${inventory.sync.horizon-days:365}") int horizonDays) {
        this.horizonDays = horizonDays;
    }

    public InventoryReconciliationRequest toRequest(String propertyId, List<RoomOutletTypeEntity> roomTypes) {
        UUID propertyUuid = parsePropertyUuid(propertyId);
        LocalDate fromDate = LocalDate.now();
        LocalDate toDate = fromDate.plusDays(Math.max(horizonDays, 1));

        List<InventoryReconciliationRequest.RoomTypeInventoryInput> normalizedRoomTypes = roomTypes.stream()
            .sorted(Comparator.comparing(entity -> safe(entity.getRoomName()), String.CASE_INSENSITIVE_ORDER))
            .map(roomType -> new InventoryReconciliationRequest.RoomTypeInventoryInput(
                roomTypeUuid(propertyId, roomType),
                Boolean.TRUE.equals(roomType.getAvailableForSell()) ? safeQuantity(roomType.getQuantity()) : 0
            ))
            .toList();

        return new InventoryReconciliationRequest(propertyUuid, fromDate, toDate, normalizedRoomTypes);
    }

    public RoomMasterSyncRequest toRoomMasterSyncRequest(
        String propertyId,
        List<InventoryRoomEntity> rooms,
        List<RoomOutletTypeEntity> roomTypes
    ) {
        UUID propertyUuid = parsePropertyUuid(propertyId);
        LocalDate businessDate = LocalDate.now();
        Map<String, RoomOutletTypeEntity> outletTypeByName = buildRoomTypeByName(roomTypes);

        List<RoomMasterSyncRequest.RoomMasterUnit> normalizedRooms = rooms.stream()
            .sorted(Comparator.comparing(entity -> safe(entity.getRoomNumber()), String.CASE_INSENSITIVE_ORDER))
            .map(room -> new RoomMasterSyncRequest.RoomMasterUnit(
                resolveRoomTypeUuid(propertyId, room.getRoomTypeName(), outletTypeByName),
                safe(room.getRoomTypeName()),
                safe(room.getRoomNumber()),
                safe(room.getFloorName()),
                null,
                null,
                null,
                false,
                true
            ))
            .toList();

        return new RoomMasterSyncRequest(propertyUuid, businessDate, normalizedRooms);
    }

    private Map<String, RoomOutletTypeEntity> buildRoomTypeByName(List<RoomOutletTypeEntity> roomTypes) {
        Map<String, RoomOutletTypeEntity> outletTypeByName = new HashMap<>();
        for (RoomOutletTypeEntity roomType : roomTypes) {
            String key = safe(roomType.getRoomName()).toLowerCase(Locale.ROOT);
            if (!key.isBlank()) {
                outletTypeByName.putIfAbsent(key, roomType);
            }
        }
        return outletTypeByName;
    }

    private UUID resolveRoomTypeUuid(String propertyId, String roomTypeName, Map<String, RoomOutletTypeEntity> outletTypeByName) {
        RoomOutletTypeEntity roomType = outletTypeByName.get(safe(roomTypeName).toLowerCase(Locale.ROOT));
        return roomType == null
            ? roomTypeUuidFromName(propertyId, roomTypeName)
            : roomTypeUuid(propertyId, roomType);
    }

    private UUID parsePropertyUuid(String propertyId) {
        try {
            return UUID.fromString(propertyId);
        } catch (IllegalArgumentException ex) {
            return deterministicUuid("property", propertyId);
        }
    }

    private UUID roomTypeUuid(String propertyId, RoomOutletTypeEntity roomType) {
        String roomKey = roomType.getRoomCode();
        if (roomKey == null || roomKey.isBlank()) {
            roomKey = safe(roomType.getRoomName());
        }
        return deterministicUuid(propertyId, roomKey.isBlank() ? "unknown" : roomKey);
    }

    public UUID roomTypeUuidFromName(String propertyId, String roomTypeName) {
        String roomKey = safe(roomTypeName);
        return deterministicUuid(propertyId, roomKey.isBlank() ? "unknown" : roomKey);
    }

    private UUID deterministicUuid(String namespace, String value) {
        String payload = (namespace + ":" + value).toLowerCase(Locale.ROOT);
        return UUID.nameUUIDFromBytes(payload.getBytes(StandardCharsets.UTF_8));
    }

    private String safe(String value) {
        return value == null ? "" : value;
    }

    private int safeQuantity(Integer quantity) {
        return quantity == null || quantity < 0 ? 0 : quantity;
    }
}

package com.pms.property.integration.inventory.service;

import com.pms.property.domain.room.entity.RoomOutletTypeEntity;
import com.pms.property.integration.inventory.dto.InventoryReconciliationRequest;
import com.pms.property.integration.inventory.dto.RoomMasterSyncRequest;
import com.pms.property.domain.room.entity.InventoryRoomEntity;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.UUID;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

@Component
public class InventorySyncPayloadMapper {

    private final int horizonDays;

    public InventorySyncPayloadMapper(@Value("${inventory.sync.horizon-days:365}") int horizonDays) {
        this.horizonDays = horizonDays;
    }

    public InventoryReconciliationRequest toRequest(String propertyId, List<RoomOutletTypeEntity> roomTypes) {
        UUID propertyUuid = parsePropertyUuid(propertyId);
        LocalDate fromDate = LocalDate.now();
        LocalDate toDate = fromDate.plusDays(Math.max(horizonDays, 1));

        List<InventoryReconciliationRequest.RoomTypeInventoryInput> normalizedRoomTypes = roomTypes.stream()
            .sorted(Comparator.comparing(entity -> safe(entity.getRoomName()), String.CASE_INSENSITIVE_ORDER))
            .map(roomType -> new InventoryReconciliationRequest.RoomTypeInventoryInput(
                roomTypeUuid(propertyId, roomType),
                Boolean.TRUE.equals(roomType.getAvailableForSell()) ? safeQuantity(roomType.getQuantity()) : 0
            ))
            .toList();

        return new InventoryReconciliationRequest(propertyUuid, fromDate, toDate, normalizedRoomTypes);
    }

    public RoomMasterSyncRequest toRoomMasterSyncRequest(
        String propertyId,
        List<InventoryRoomEntity> rooms,
        List<RoomOutletTypeEntity> roomTypes
    ) {
        UUID propertyUuid = parsePropertyUuid(propertyId);
        LocalDate fromDate = LocalDate.now();
        LocalDate toDate = fromDate.plusDays(Math.max(horizonDays, 1));
        Map<String, RoomOutletTypeEntity> outletTypeByName = buildRoomTypeByName(roomTypes);

        List<RoomMasterSyncRequest.RoomMasterUnit> normalizedRooms = rooms.stream()
            .sorted(Comparator.comparing(entity -> safe(entity.getRoomNumber()), String.CASE_INSENSITIVE_ORDER))
            .map(room -> new RoomMasterSyncRequest.RoomMasterUnit(
                resolveRoomTypeUuid(propertyId, room.getRoomTypeName(), outletTypeByName),
                safe(room.getRoomTypeName()),
                safe(room.getRoomNumber()),
                safe(room.getFloorName()),
                null,
                null,
                null,
                false,
                true
            ))
            .toList();

        return new RoomMasterSyncRequest(propertyUuid, fromDate, toDate, normalizedRooms);
    }

    private Map<String, RoomOutletTypeEntity> buildRoomTypeByName(List<RoomOutletTypeEntity> roomTypes) {
        Map<String, RoomOutletTypeEntity> outletTypeByName = new HashMap<>();
        for (RoomOutletTypeEntity roomType : roomTypes) {
            String key = safe(roomType.getRoomName()).toLowerCase(Locale.ROOT);
            if (!key.isBlank()) {
                outletTypeByName.putIfAbsent(key, roomType);
            }
        }
        return outletTypeByName;
    }

    private UUID resolveRoomTypeUuid(String propertyId, String roomTypeName, Map<String, RoomOutletTypeEntity> outletTypeByName) {
        RoomOutletTypeEntity roomType = outletTypeByName.get(safe(roomTypeName).toLowerCase(Locale.ROOT));
        return roomType == null
            ? roomTypeUuidFromName(propertyId, roomTypeName)
            : roomTypeUuid(propertyId, roomType);
    }

    private UUID parsePropertyUuid(String propertyId) {
        try {
            return UUID.fromString(propertyId);
        } catch (IllegalArgumentException ex) {
            return deterministicUuid("property", propertyId);
        }
    }

    private UUID roomTypeUuid(String propertyId, RoomOutletTypeEntity roomType) {
        String roomKey = roomType.getRoomCode();
        if (roomKey == null || roomKey.isBlank()) {
            roomKey = safe(roomType.getRoomName());
        }
        return deterministicUuid(propertyId, roomKey.isBlank() ? "unknown" : roomKey);
    }

    public UUID roomTypeUuidFromName(String propertyId, String roomTypeName) {
        String roomKey = safe(roomTypeName);
        return deterministicUuid(propertyId, roomKey.isBlank() ? "unknown" : roomKey);
    }

    private UUID deterministicUuid(String namespace, String value) {
        String payload = (namespace + ":" + value).toLowerCase(Locale.ROOT);
        return UUID.nameUUIDFromBytes(payload.getBytes(StandardCharsets.UTF_8));
    }

    private String safe(String value) {
        return value == null ? "" : value;
    }

    private int safeQuantity(Integer quantity) {
        return quantity == null || quantity < 0 ? 0 : quantity;
    }
}

package com.pms.property.integration.inventory.service;

import com.pms.property.common.exception.BadRequestException;
import com.pms.property.domain.room.entity.InventoryRoomEntity;
import com.pms.property.domain.room.entity.RoomOutletTypeEntity;
import com.pms.property.domain.room.repository.InventoryRoomRepository;
import com.pms.property.domain.room.repository.RoomOutletTypeRepository;
import com.pms.property.integration.inventory.dto.InventoryReconciliationRequest;
import com.pms.property.integration.inventory.dto.RoomMasterSyncRequest;
import com.pms.property.integration.inventory.dto.InventorySyncStatusResponse;
import com.pms.property.integration.inventory.entity.InventorySyncStateEntity;
import com.pms.property.integration.inventory.entity.InventorySyncStatus;
import com.pms.property.integration.inventory.exception.InventorySyncException;
import com.pms.property.integration.inventory.repository.InventorySyncStateRepository;
import java.time.Instant;
import java.util.List;
import java.util.UUID;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

@Service
public class InventorySyncService {

    private final RoomOutletTypeRepository roomOutletTypeRepository;
    private final InventoryRoomRepository inventoryRoomRepository;
    private final InventorySyncPayloadMapper payloadMapper;
    private final InventorySyncClient inventorySyncClient;
    private final InventorySyncStateRepository syncStateRepository;

    public InventorySyncService(
        RoomOutletTypeRepository roomOutletTypeRepository,
        InventoryRoomRepository inventoryRoomRepository,
        InventorySyncPayloadMapper payloadMapper,
        InventorySyncClient inventorySyncClient,
        InventorySyncStateRepository syncStateRepository
    ) {
        this.roomOutletTypeRepository = roomOutletTypeRepository;
        this.inventoryRoomRepository = inventoryRoomRepository;
        this.payloadMapper = payloadMapper;
        this.inventorySyncClient = inventorySyncClient;
        this.syncStateRepository = syncStateRepository;
    }

    public void requestSyncAfterCommit(String propertyId) {
        if (TransactionSynchronizationManager.isSynchronizationActive()) {
            registerAfterCommitSync(propertyId);
            markPending(propertyId);
            return;
        }

        syncSilently(propertyId);
    }

    public InventorySyncStatusResponse syncNow(String propertyId) {
        return toStatusResponse(synchronizeProperty(propertyId));
    }

    public InventorySyncStatusResponse getStatus(String propertyId) {
        return toStatusResponse(loadStateOrThrow(propertyId));
    }

    private void syncSilently(String propertyId) {
        try {
            synchronizeProperty(propertyId);
        } catch (InventorySyncException ignored) {
            // Sync state is already persisted with FAILED status.
        }
    }

    private InventorySyncStateEntity synchronizeProperty(String propertyId) {
        List<InventoryRoomEntity> inventoryRooms = inventoryRoomRepository.findAllByPropertyId(propertyId);
        List<RoomOutletTypeEntity> roomTypes = loadRoomTypesOrThrow(propertyId);
        String requestId = newRequestId();

        InventoryReconciliationRequest request = payloadMapper.toRequest(propertyId, roomTypes);

        try {
            if (!inventoryRooms.isEmpty()) {
                syncRoomMaster(propertyId, inventoryRooms, roomTypes, requestId);
            }
            inventorySyncClient.reconcile(request, requestId);
            return markSuccess(propertyId, requestId);
        } catch (RuntimeException ex) {
            throw persistFailureAndWrap(propertyId, requestId, ex);
        }
    }

    private void markPending(String propertyId) {
        updateState(propertyId, InventorySyncStatus.PENDING, null, null, false);
    }

    private void syncRoomMaster(
        String propertyId,
        List<InventoryRoomEntity> rooms,
        List<RoomOutletTypeEntity> roomTypes,
        String requestId
    ) {
        RoomMasterSyncRequest roomMasterRequest = payloadMapper.toRoomMasterSyncRequest(propertyId, rooms, roomTypes);
        inventorySyncClient.syncRoomMaster(roomMasterRequest, requestId);
    }

    private InventorySyncStateEntity markSuccess(String propertyId, String requestId) {
        return updateState(propertyId, InventorySyncStatus.SUCCESS, requestId, null, true);
    }

    private RuntimeException persistFailureAndWrap(String propertyId, String requestId, RuntimeException ex) {
        updateState(propertyId, InventorySyncStatus.FAILED, requestId, trimError(ex.getMessage()), false);
        return ex instanceof InventorySyncException
            ? (InventorySyncException) ex
            : new InventorySyncException("Inventory sync failed", ex);
    }

    private InventorySyncStateEntity updateState(
        String propertyId,
        InventorySyncStatus status,
        String requestId,
        String error,
        boolean success
    ) {
        InventorySyncStateEntity state = loadOrCreateState(propertyId);

        state.setStatus(status);
        if (requestId != null) {
            state.setLastRequestId(requestId);
        }
        state.setLastError(error);

        int retries = state.getRetryCount() == null ? 0 : state.getRetryCount();
        state.setRetryCount(success ? 0 : retries + 1);
        if (success) {
            state.setLastSyncedAt(Instant.now());
        }

        return syncStateRepository.save(state);
    }

    private InventorySyncStateEntity loadStateOrThrow(String propertyId) {
        return syncStateRepository.findById(propertyId)
            .orElseThrow(() -> new BadRequestException("No sync state found for property: " + propertyId));
    }

    private InventorySyncStateEntity loadOrCreateState(String propertyId) {
        return syncStateRepository.findById(propertyId).orElseGet(() -> {
            InventorySyncStateEntity created = new InventorySyncStateEntity();
            created.setPropertyId(propertyId);
            created.setRetryCount(0);
            return created;
        });
    }

    private List<RoomOutletTypeEntity> loadRoomTypesOrThrow(String propertyId) {
        List<RoomOutletTypeEntity> roomTypes = roomOutletTypeRepository.findAllByPropertyId(propertyId);
        if (roomTypes.isEmpty()) {
            throw new BadRequestException("Cannot sync inventory. No room outlet types found for property: " + propertyId);
        }
        return roomTypes;
    }

    private String newRequestId() {
        return UUID.randomUUID().toString();
    }

    private void registerAfterCommitSync(String propertyId) {
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                syncSilently(propertyId);
            }
        });
    }

    private String trimError(String error) {
        if (error == null) {
            return null;
        }
        return error.length() <= 1000 ? error : error.substring(0, 1000);
    }

    private InventorySyncStatusResponse toStatusResponse(InventorySyncStateEntity state) {
        return new InventorySyncStatusResponse(
            state.getPropertyId(),
            state.getStatus().name(),
            state.getLastRequestId(),
            state.getLastError(),
            state.getRetryCount(),
            state.getLastSyncedAt() == null ? null : state.getLastSyncedAt().toString(),
            state.getUpdatedAt() == null ? null : state.getUpdatedAt().toString()
        );
    }

}

package com.pms.property.integration.inventory.service;

import com.pms.property.common.exception.BadRequestException;
import com.pms.property.domain.room.entity.InventoryRoomEntity;
import com.pms.property.domain.room.entity.RoomOutletTypeEntity;
import com.pms.property.domain.room.repository.InventoryRoomRepository;
import com.pms.property.domain.room.repository.RoomOutletTypeRepository;
import com.pms.property.integration.inventory.dto.InventoryReconciliationRequest;
import com.pms.property.integration.inventory.dto.RoomMasterSyncRequest;
import com.pms.property.integration.inventory.dto.InventorySyncStatusResponse;
import com.pms.property.integration.inventory.entity.InventorySyncStateEntity;
import com.pms.property.integration.inventory.entity.InventorySyncStatus;
import com.pms.property.integration.inventory.exception.InventorySyncException;
import com.pms.property.integration.inventory.repository.InventorySyncStateRepository;
import java.time.Instant;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.UUID;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

@Slf4j
@Service
public class InventorySyncService {

    private final RoomOutletTypeRepository roomOutletTypeRepository;
    private final InventoryRoomRepository inventoryRoomRepository;
    private final InventorySyncPayloadMapper payloadMapper;
    private final InventorySyncClient inventorySyncClient;
    private final InventorySyncStateRepository syncStateRepository;

    public InventorySyncService(
        RoomOutletTypeRepository roomOutletTypeRepository,
        InventoryRoomRepository inventoryRoomRepository,
        InventorySyncPayloadMapper payloadMapper,
        InventorySyncClient inventorySyncClient,
        InventorySyncStateRepository syncStateRepository
    ) {
        this.roomOutletTypeRepository = roomOutletTypeRepository;
        this.inventoryRoomRepository = inventoryRoomRepository;
        this.payloadMapper = payloadMapper;
        this.inventorySyncClient = inventorySyncClient;
        this.syncStateRepository = syncStateRepository;
    }

    public void requestSyncAfterCommit(String propertyId) {
        if (TransactionSynchronizationManager.isSynchronizationActive()) {
            registerAfterCommitSync(propertyId);
            markPending(propertyId);
            return;
        }

        syncSilently(propertyId);
    }

    public InventorySyncStatusResponse syncNow(String propertyId) {
        return toStatusResponse(synchronizeProperty(propertyId));
    }

    public InventorySyncStatusResponse getStatus(String propertyId) {
        return toStatusResponse(loadStateOrThrow(propertyId));
    }

    private void syncSilently(String propertyId) {
        try {
            synchronizeProperty(propertyId);
        } catch (InventorySyncException ex) {
            // Sync state is already persisted with FAILED status.
            log.warn("Inventory sync failed for property {}: {}", propertyId, ex.getMessage());
        }
    }

    private InventorySyncStateEntity synchronizeProperty(String propertyId) {
        List<InventoryRoomEntity> inventoryRooms = inventoryRoomRepository.findAllByPropertyId(propertyId);
        List<RoomOutletTypeEntity> roomTypes = loadRoomTypesOrThrow(propertyId);
        String requestId = newRequestId();

        InventoryReconciliationRequest request = payloadMapper.toRequest(propertyId, roomTypes);

        RuntimeException roomMasterError = null;
        if (!inventoryRooms.isEmpty()) {
            try {
                syncRoomMaster(propertyId, inventoryRooms, roomTypes, requestId);
            } catch (RuntimeException ex) {
                roomMasterError = toSyncException("Room master sync failed", ex);
            }
        }

        RuntimeException reconcileError = null;
        try {
            inventorySyncClient.reconcile(request, requestId);
        } catch (RuntimeException ex) {
            reconcileError = toSyncException("Inventory reconciliation failed", ex);
        }

        if (roomMasterError == null && reconcileError == null) {
            return markSuccess(propertyId, requestId);
        }

        RuntimeException primary = reconcileError != null ? reconcileError : roomMasterError;
        String failureMessage = buildFailureMessage(roomMasterError, reconcileError);
        throw persistFailureAndWrap(propertyId, requestId, new InventorySyncException(failureMessage, primary));
    }

    private void markPending(String propertyId) {
        updateState(propertyId, InventorySyncStatus.PENDING, null, null, false);
    }

    private void syncRoomMaster(
        String propertyId,
        List<InventoryRoomEntity> rooms,
        List<RoomOutletTypeEntity> roomTypes,
        String requestId
    ) {
        RoomMasterSyncRequest roomMasterRequest = payloadMapper.toRoomMasterSyncRequest(propertyId, rooms, roomTypes);
        inventorySyncClient.syncRoomMaster(roomMasterRequest, requestId);
    }

    private InventorySyncStateEntity markSuccess(String propertyId, String requestId) {
        return updateState(propertyId, InventorySyncStatus.SUCCESS, requestId, null, true);
    }

    private RuntimeException persistFailureAndWrap(String propertyId, String requestId, RuntimeException ex) {
        updateState(propertyId, InventorySyncStatus.FAILED, requestId, trimError(ex.getMessage()), false);
        return ex instanceof InventorySyncException
            ? (InventorySyncException) ex
            : new InventorySyncException("Inventory sync failed", ex);
    }

    private InventorySyncStateEntity updateState(
        String propertyId,
        InventorySyncStatus status,
        String requestId,
        String error,
        boolean success
    ) {
        InventorySyncStateEntity state = loadOrCreateState(propertyId);

        state.setStatus(status);
        if (requestId != null) {
            state.setLastRequestId(requestId);
        }
        state.setLastError(error);

        int retries = state.getRetryCount() == null ? 0 : state.getRetryCount();
        state.setRetryCount(success ? 0 : retries + 1);
        if (success) {
            state.setLastSyncedAt(Instant.now());
        }

        return syncStateRepository.save(state);
    }

    private InventorySyncStateEntity loadStateOrThrow(String propertyId) {
        return syncStateRepository.findById(propertyId)
            .orElseThrow(() -> new BadRequestException("No sync state found for property: " + propertyId));
    }

    private InventorySyncStateEntity loadOrCreateState(String propertyId) {
        return syncStateRepository.findById(propertyId).orElseGet(() -> {
            InventorySyncStateEntity created = new InventorySyncStateEntity();
            created.setPropertyId(propertyId);
            created.setRetryCount(0);
            return created;
        });
    }

    private List<RoomOutletTypeEntity> loadRoomTypesOrThrow(String propertyId) {
        List<RoomOutletTypeEntity> roomTypes = roomOutletTypeRepository.findAllByPropertyId(propertyId);
        if (roomTypes.isEmpty()) {
            throw new BadRequestException("Cannot sync inventory. No room outlet types found for property: " + propertyId);
        }
        validateRoomTypeKeys(propertyId, roomTypes);
        return roomTypes;
    }

    private void validateRoomTypeKeys(String propertyId, List<RoomOutletTypeEntity> roomTypes) {
        Set<String> seenKeys = new HashSet<>();
        for (RoomOutletTypeEntity roomType : roomTypes) {
            String key = roomTypeSyncKey(roomType);
            if (key.isBlank()) {
                throw new BadRequestException("Cannot sync inventory. Room type key is missing for property: " + propertyId);
            }
            if (!seenKeys.add(key.toLowerCase(Locale.ROOT))) {
                throw new BadRequestException("Cannot sync inventory. Duplicate room type key found: " + key);
            }
        }
    }

    private String roomTypeSyncKey(RoomOutletTypeEntity roomType) {
        String code = roomType.getRoomCode();
        if (code != null && !code.isBlank()) {
            return code.trim();
        }
        String name = roomType.getRoomName();
        return name == null ? "" : name.trim();
    }

    private RuntimeException toSyncException(String message, RuntimeException ex) {
        return ex instanceof InventorySyncException
            ? ex
            : new InventorySyncException(message, ex);
    }

    private String buildFailureMessage(RuntimeException roomMasterError, RuntimeException reconcileError) {
        if (roomMasterError != null && reconcileError != null) {
            return "Room master sync and inventory reconciliation both failed";
        }
        if (roomMasterError != null) {
            return "Room master sync failed";
        }
        return "Inventory reconciliation failed";
    }

    private String newRequestId() {
        return UUID.randomUUID().toString();
    }

    private void registerAfterCommitSync(String propertyId) {
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                syncSilently(propertyId);
            }
        });
    }

    private String trimError(String error) {
        if (error == null) {
            return null;
        }
        return error.length() <= 1000 ? error : error.substring(0, 1000);
    }

    private InventorySyncStatusResponse toStatusResponse(InventorySyncStateEntity state) {
        return new InventorySyncStatusResponse(
            state.getPropertyId(),
            state.getStatus().name(),
            state.getLastRequestId(),
            state.getLastError(),
            state.getRetryCount(),
            state.getLastSyncedAt() == null ? null : state.getLastSyncedAt().toString(),
            state.getUpdatedAt() == null ? null : state.getUpdatedAt().toString()
        );
    }

}

package com.pms.property.upload.service;

import com.pms.property.common.exception.BadRequestException;
import com.pms.property.upload.dto.UploadImageResponse;
import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardCopyOption;
import java.util.Locale;
import java.util.Set;
import java.util.UUID;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.web.multipart.MultipartFile;

@Service
public class LocalImageStorageServiceImpl implements LocalImageStorageService {

    private static final Set<String> ALLOWED_EXTENSIONS = Set.of(".jpg", ".jpeg", ".png", ".webp", ".gif");

    private final Path uploadRoot;
    private final long maxUploadBytes;

    @Autowired
    public LocalImageStorageServiceImpl(
        @Value("${app.upload.base-dir:uploads}") String uploadBaseDir,
        @Value("${app.upload.max-bytes:5242880}") long maxUploadBytes
    ) {
        this.uploadRoot = Paths.get(uploadBaseDir).toAbsolutePath().normalize();
        this.maxUploadBytes = maxUploadBytes;
    }

    LocalImageStorageServiceImpl(String uploadBaseDir, long maxUploadBytes, boolean ignored) {
        this.uploadRoot = Paths.get(uploadBaseDir).toAbsolutePath().normalize();
        this.maxUploadBytes = maxUploadBytes;
    }

    @Override
    public UploadImageResponse store(MultipartFile file) {
        validate(file);

        String extension = resolveExtension(file);
        String storedFileName = UUID.randomUUID() + extension;

        try {
            Files.createDirectories(uploadRoot);
            Path target = uploadRoot.resolve(storedFileName);
            try (InputStream inputStream = file.getInputStream()) {
                Files.copy(inputStream, target, StandardCopyOption.REPLACE_EXISTING);
            }
            return new UploadImageResponse(storedFileName, "/uploads/" + storedFileName, file.getSize(), file.getContentType());
        } catch (IOException ex) {
            throw new BadRequestException("Could not store uploaded image");
        }
    }

    @Override
    public void deleteByPublicUrl(String publicUrlOrFileName) {
        String fileName = extractFileName(publicUrlOrFileName);
        if (fileName.isBlank()) {
            return;
        }

        Path target = uploadRoot.resolve(fileName).normalize();
        if (!target.startsWith(uploadRoot)) {
            return;
        }

        try {
            Files.deleteIfExists(target);
        } catch (IOException ignored) {
            // Best-effort cleanup should not block business operations.
        }
    }

    private void validate(MultipartFile file) {
        if (file == null || file.isEmpty()) {
            throw new BadRequestException("Image file is required");
        }

        if (file.getSize() > maxUploadBytes) {
            throw new BadRequestException("Image size exceeds configured upload limit");
        }

        String contentType = file.getContentType();
        if (contentType == null || !contentType.toLowerCase(Locale.ENGLISH).startsWith("image/")) {
            throw new BadRequestException("Only image uploads are allowed");
        }

        String extension = resolveExtension(file);
        if (!ALLOWED_EXTENSIONS.contains(extension)) {
            throw new BadRequestException("Unsupported image type. Allowed: jpg, jpeg, png, webp, gif");
        }
    }

    private String resolveExtension(MultipartFile file) {
        String originalName = file.getOriginalFilename();
        if (originalName != null) {
            int dotIndex = originalName.lastIndexOf('.');
            if (dotIndex >= 0 && dotIndex < originalName.length() - 1) {
                return originalName.substring(dotIndex).toLowerCase(Locale.ENGLISH);
            }
        }

        String contentType = file.getContentType();
        if (contentType == null) {
            return "";
        }
        return switch (contentType.toLowerCase(Locale.ENGLISH)) {
            case "image/jpeg" -> ".jpg";
            case "image/png" -> ".png";
            case "image/webp" -> ".webp";
            case "image/gif" -> ".gif";
            default -> "";
        };
    }

    private String extractFileName(String publicUrlOrFileName) {
        if (publicUrlOrFileName == null) {
            return "";
        }
        String value = publicUrlOrFileName.trim();
        if (value.isEmpty()) {
            return "";
        }
        int slash = value.lastIndexOf('/');
        String fileName = slash >= 0 ? value.substring(slash + 1) : value;
        if (fileName.contains("..") || fileName.contains("\\") || fileName.contains("/")) {
            return "";
        }
        return fileName;
    }
}

package com.pms.inventory.common.config;

import io.swagger.v3.oas.models.OpenAPI;
import io.swagger.v3.oas.models.info.Contact;
import io.swagger.v3.oas.models.info.Info;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class OpenApiConfig {

	@Bean
	public OpenAPI inventoryOpenApi() {
		return new OpenAPI()
				.info(new Info()
						.title("PMS Inventory API")
						.version("v1")
						.description("Room-type-level inventory management API")
						.contact(new Contact().name("PMS Platform Team")));
	}
}

