package com.pms.inventory.common.security;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.pms.inventory.common.response.ApiResponse;
import com.pms.security.jwt.AccessTokenVerifier;
import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.List;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

@Slf4j
@Component
@RequiredArgsConstructor
public class AuthFilter extends OncePerRequestFilter {

    private static final String AUTHORIZATION_HEADER = "Authorization";
    private static final String BEARER_PREFIX = "Bearer ";

    private final ObjectMapper objectMapper;
    private final JwtAccessTokenValidator jwtAccessTokenValidator;

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain filterChain)
            throws ServletException, IOException {
        if ("OPTIONS".equalsIgnoreCase(request.getMethod()) || isPublicPath(request.getRequestURI())) {
            filterChain.doFilter(request, response);
            return;
        }

        String authHeader = request.getHeader(AUTHORIZATION_HEADER);
        if (authHeader == null || !authHeader.startsWith(BEARER_PREFIX)) {
            writeUnauthorized(response, "Missing or invalid Authorization header");
            return;
        }

        AccessTokenVerifier.VerifiedAccessToken verifiedToken = jwtAccessTokenValidator
                .validateAccessToken(authHeader.substring(BEARER_PREFIX.length()))
                .orElse(null);

        if (verifiedToken == null) {
            writeUnauthorized(response, "Invalid or expired access token");
            return;
        }

        List<SimpleGrantedAuthority> authorities = verifiedToken.roles().stream()
                .map(String::trim)
                .filter(role -> !role.isBlank())
                .map(String::toUpperCase)
                .flatMap(role -> role.startsWith("ROLE_")
                        ? java.util.stream.Stream.of(role, role.substring("ROLE_".length()))
                        : java.util.stream.Stream.of("ROLE_" + role, role))
                .distinct()
                .map(SimpleGrantedAuthority::new)
                .toList();

        if (log.isDebugEnabled()) {
            log.debug("Authenticated request method={} path={} user={} authorities={}",
                    request.getMethod(), request.getRequestURI(), verifiedToken.username(), authorities);
        }

        UsernamePasswordAuthenticationToken authentication = new UsernamePasswordAuthenticationToken(
                verifiedToken.username(), null, authorities);
        SecurityContextHolder.getContext().setAuthentication(authentication);
        try {
            filterChain.doFilter(request, response);
        } finally {
            SecurityContextHolder.clearContext();
        }
    }

    private boolean isPublicPath(String path) {
        return path.startsWith("/v3/api-docs")
                || path.startsWith("/swagger-ui")
                || path.equals("/swagger-ui.html")
                || path.equals("/error");
    }

    private void writeUnauthorized(HttpServletResponse response, String message) throws IOException {
        response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
        response.setContentType("application/json");
        response.getWriter().write(objectMapper.writeValueAsString(ApiResponse.fail(message)));
    }
}

package com.pms.inventory.common.security;

import com.pms.security.jwt.AccessTokenVerifier;
import java.util.Optional;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

@Component
public class JwtAccessTokenValidator {

    private final AccessTokenVerifier accessTokenVerifier;

    public JwtAccessTokenValidator(@Value("${security.jwt.secret}") String secret) {
        this.accessTokenVerifier = new AccessTokenVerifier(secret);
    }

    public Optional<AccessTokenVerifier.VerifiedAccessToken> validateAccessToken(String token) {
        return accessTokenVerifier.verify(token);
    }
}

