import com.pms.inventory.inventory.dto.response.InventoryReservationResponse;

public interface InventoryReservationService {

    InventoryReservationResponse reserveInventory(ReserveInventoryRequest request);

    InventoryReservationResponse releaseInventory(String reservationId);
