package com.pms.inventory.inventory.service.impl;

import com.pms.inventory.inventory.dto.response.DailyInventoryResponse;
import com.pms.inventory.inventory.dto.response.InventoryAvailabilityResponse;
import com.pms.inventory.inventory.entity.RoomTypeInventoryDaily;
import com.pms.inventory.inventory.repository.RoomTypeInventoryDailyRepository;
import com.pms.inventory.inventory.service.InventoryAvailabilityService;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.List;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;

@Service
@RequiredArgsConstructor
public class InventoryAvailabilityServiceImpl implements InventoryAvailabilityService {

    private final RoomTypeInventoryDailyRepository dailyRepository;

    @Override
    public InventoryAvailabilityResponse checkAvailability(
            String propertyId,
            Long roomTypeId,
            LocalDate checkInDate,
            LocalDate checkOutDate,
            int quantity) {

        long nights = ChronoUnit.DAYS.between(checkInDate, checkOutDate);
        List<RoomTypeInventoryDaily> rows = dailyRepository
                .findByPropertyIdAndRoomTypeIdAndBusinessDateGreaterThanEqualAndBusinessDateLessThanOrderByBusinessDate(
                        propertyId, roomTypeId, checkInDate, checkOutDate);

        if (rows.size() != nights) {
            return new InventoryAvailabilityResponse(
                    propertyId,
                    roomTypeId,
                    checkInDate,
                    checkOutDate,
                    quantity,
                    false,
                    0);
        }

        int minAvailable = rows.stream()
                .mapToInt(RoomTypeInventoryDaily::availableInventory)
                .min()
                .orElse(0);

        return new InventoryAvailabilityResponse(
                propertyId,
                roomTypeId,
                checkInDate,
                checkOutDate,
                quantity,
                minAvailable >= quantity,
                Math.max(minAvailable, 0));
    }

    @Override
    public List<DailyInventoryResponse> getDailyInventory(String propertyId, LocalDate businessDate) {
        return dailyRepository.findByPropertyIdAndBusinessDateOrderByRoomTypeId(propertyId, businessDate).stream()
                .map(row -> new DailyInventoryResponse(
                        row.getPropertyId(),
                        row.getRoomTypeId(),
                        row.getBusinessDate(),
                        row.getTotalInventory(),
                        row.getReservedCount(),
                        row.getBlockedCount(),
                        row.availableInventory()))
                .toList();
    }
}

package com.pms.inventory.inventory.service.impl;

import com.pms.inventory.common.exception.IdempotencyConflictException;
import com.pms.inventory.common.exception.InventoryConflictException;
import com.pms.inventory.common.exception.ResourceNotFoundException;
import com.pms.inventory.inventory.dto.request.ReserveInventoryRequest;
import com.pms.inventory.inventory.dto.response.InventoryReservationResponse;
import com.pms.inventory.inventory.entity.InventoryReservation;
import com.pms.inventory.inventory.entity.InventoryReservationStatus;
import com.pms.inventory.inventory.entity.RoomTypeInventoryDaily;
import com.pms.inventory.inventory.repository.InventoryReservationRepository;
import com.pms.inventory.inventory.repository.RoomTypeInventoryDailyRepository;
import com.pms.inventory.inventory.service.InventoryReservationService;
import jakarta.transaction.Transactional;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.List;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.dao.OptimisticLockingFailureException;
import org.springframework.retry.annotation.Backoff;
import org.springframework.retry.annotation.Recover;
import org.springframework.retry.annotation.Retryable;
import org.springframework.stereotype.Service;

@Slf4j
@Service
@RequiredArgsConstructor
public class InventoryReservationServiceImpl implements InventoryReservationService {

    private final InventoryReservationRepository reservationRepository;
    private final RoomTypeInventoryDailyRepository dailyRepository;

    @Override
    @Transactional
    @Retryable(
            retryFor = OptimisticLockingFailureException.class,
            maxAttemptsExpression = "${inventory.reservation.max-retries:3}",
            backoff = @Backoff(delay = 50, multiplier = 2.0))
    public InventoryReservationResponse reserveInventory(ReserveInventoryRequest request) {
        log.info("Inventory reserve attempt propertyId={} roomTypeId={} reservationId={} checkIn={} checkOut={} quantity={}",
                request.propertyId(), request.roomTypeId(), request.reservationId(), request.checkInDate(), request.checkOutDate(), request.quantity());

        InventoryReservation existing = reservationRepository.findByReservationId(request.reservationId()).orElse(null);
        if (existing != null) {
            validateIdempotent(existing, request);
            return toResponse(existing, true);
        }

        List<RoomTypeInventoryDaily> rows = getRowsForStay(
                request.propertyId(), request.roomTypeId(), request.checkInDate(), request.checkOutDate());

        for (RoomTypeInventoryDaily row : rows) {
            int available = row.availableInventory();
            if (available < request.quantity()) {
                throw new InventoryConflictException("Inventory is not available for the requested dates");
            }
        }

        for (RoomTypeInventoryDaily row : rows) {
            row.setReservedCount(row.getReservedCount() + request.quantity());
        }
        dailyRepository.saveAll(rows);

        InventoryReservation reservation = InventoryReservation.builder()
                .reservationId(request.reservationId())
                .propertyId(request.propertyId())
                .roomTypeId(request.roomTypeId())
                .checkInDate(request.checkInDate())
                .checkOutDate(request.checkOutDate())
                .quantity(request.quantity())
                .status(InventoryReservationStatus.RESERVED)
                .build();

        reservationRepository.save(reservation);

        log.info("Inventory reserve success propertyId={} roomTypeId={} reservationId={}",
                request.propertyId(), request.roomTypeId(), request.reservationId());

        return toResponse(reservation, false);
    }

    @Recover
    public InventoryReservationResponse recoverFromOptimisticLock(
            OptimisticLockingFailureException ex,
            ReserveInventoryRequest request) {
        log.warn("Inventory reserve failed after retries reservationId={} message={}", request.reservationId(), ex.getMessage());
        throw new InventoryConflictException("Inventory changed due to concurrent updates. Please retry.");
    }

    @Override
    @Transactional
    public InventoryReservationResponse releaseInventory(String reservationId) {
        InventoryReservation reservation = reservationRepository.findByReservationId(reservationId).orElse(null);
        if (reservation == null) {
            return new InventoryReservationResponse(reservationId, null, null, null, null, 0,
                    InventoryReservationStatus.RELEASED, true);
        }

        if (reservation.getStatus() != InventoryReservationStatus.RESERVED) {
            return toResponse(reservation, true);
        }

        log.info("Inventory release attempt reservationId={} propertyId={} roomTypeId={}",
                reservation.getReservationId(), reservation.getPropertyId(), reservation.getRoomTypeId());

        List<RoomTypeInventoryDaily> rows = getRowsForStay(
                reservation.getPropertyId(),
                reservation.getRoomTypeId(),
                reservation.getCheckInDate(),
                reservation.getCheckOutDate());

        for (RoomTypeInventoryDaily row : rows) {
            int nextValue = row.getReservedCount() - reservation.getQuantity();
            if (nextValue < 0) {
                throw new InventoryConflictException("Reserved inventory would become negative during release");
            }
            row.setReservedCount(nextValue);
        }
        dailyRepository.saveAll(rows);

        reservation.setStatus(InventoryReservationStatus.RELEASED);
        reservationRepository.save(reservation);

        log.info("Inventory release success reservationId={} propertyId={} roomTypeId={}",
                reservation.getReservationId(), reservation.getPropertyId(), reservation.getRoomTypeId());

        return toResponse(reservation, false);
    }

    private List<RoomTypeInventoryDaily> getRowsForStay(
            String propertyId,
            Long roomTypeId,
            LocalDate checkInDate,
            LocalDate checkOutDate) {

        long expectedNights = ChronoUnit.DAYS.between(checkInDate, checkOutDate);
        List<RoomTypeInventoryDaily> rows = dailyRepository
                .findByPropertyIdAndRoomTypeIdAndBusinessDateGreaterThanEqualAndBusinessDateLessThanOrderByBusinessDate(
                        propertyId, roomTypeId, checkInDate, checkOutDate);

        if (rows.size() != expectedNights) {
            throw new ResourceNotFoundException("Inventory calendar is missing one or more business dates");
        }
        return rows;
    }

    private void validateIdempotent(InventoryReservation existing, ReserveInventoryRequest request) {
        boolean samePayload = existing.getPropertyId().equals(request.propertyId())
                && existing.getRoomTypeId().equals(request.roomTypeId())
                && existing.getCheckInDate().equals(request.checkInDate())
                && existing.getCheckOutDate().equals(request.checkOutDate())
                && existing.getQuantity() == request.quantity();

        if (!samePayload) {
            throw new IdempotencyConflictException("Reservation id already exists with different inventory payload");
        }

        if (existing.getStatus() != InventoryReservationStatus.RESERVED) {
            throw new IdempotencyConflictException("Reservation id exists but is no longer in RESERVED status");
        }
    }

    private InventoryReservationResponse toResponse(InventoryReservation reservation, boolean idempotent) {
        return new InventoryReservationResponse(
                reservation.getReservationId(),
                reservation.getPropertyId(),
                reservation.getRoomTypeId(),
                reservation.getCheckInDate(),
                reservation.getCheckOutDate(),
                reservation.getQuantity(),
                reservation.getStatus(),
                idempotent);
    }
}

