package com.pms.inventory.reconciliation.scheduler;

import com.pms.inventory.common.config.InventoryProperties;
import com.pms.inventory.reconciliation.service.InventoryReconciliationService;
import java.time.Duration;
import java.time.Instant;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Slf4j
@Component
@RequiredArgsConstructor
public class InventoryReconciliationScheduler {

    private final InventoryProperties properties;
    private final InventoryReconciliationService reconciliationService;

    @Scheduled(cron = "${inventory.reconciliation.cron}")
    public void runScheduledReconciliation() {
        if (!properties.getReconciliation().isEnabled()) {
            return;
        }

        for (String propertyId : properties.getReconciliation().getProperties()) {
            Instant started = Instant.now();
            try {
                reconciliationService.reconcileProperty(propertyId);
                log.info("Scheduled reconciliation success propertyId={} durationMs={}",
                        propertyId, Duration.between(started, Instant.now()).toMillis());
            } catch (Exception ex) {
                log.error("Scheduled reconciliation failed propertyId={} durationMs={} message={}",
                        propertyId, Duration.between(started, Instant.now()).toMillis(), ex.getMessage(), ex);
            }
        }
    }
}

package com.pms.inventory.reconciliation.service.impl;

import com.pms.inventory.common.config.InventoryProperties;
import com.pms.inventory.common.exception.InventoryConfigurationConflictException;
import com.pms.inventory.common.exception.ResourceNotFoundException;
import com.pms.inventory.integration.propertywizard.PropertyWizardClient;
import com.pms.inventory.integration.propertywizard.dto.PhysicalRoomDto;
import com.pms.inventory.integration.propertywizard.dto.PropertyDto;
import com.pms.inventory.integration.propertywizard.dto.RoomTypeDto;
import com.pms.inventory.inventory.entity.RoomTypeInventoryDaily;
import com.pms.inventory.inventory.repository.RoomTypeInventoryDailyRepository;
import com.pms.inventory.reconciliation.dto.response.ReconciliationStatusResponse;
import com.pms.inventory.reconciliation.dto.response.ReconciliationSummaryResponse;
import com.pms.inventory.reconciliation.entity.ReconciliationExecution;
import com.pms.inventory.reconciliation.entity.ReconciliationExecutionStatus;
import com.pms.inventory.reconciliation.repository.ReconciliationExecutionRepository;
import com.pms.inventory.reconciliation.service.InventoryReconciliationService;
import jakarta.transaction.Transactional;
import java.time.Duration;
import java.time.Instant;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.stream.Collectors;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

@Slf4j
@Service
@RequiredArgsConstructor
public class InventoryReconciliationServiceImpl implements InventoryReconciliationService {

    private final PropertyWizardClient propertyWizardClient;
    private final RoomTypeInventoryDailyRepository dailyRepository;
    private final ReconciliationExecutionRepository executionRepository;
    private final InventoryProperties inventoryProperties;

    @Override
    @Transactional
    public ReconciliationSummaryResponse reconcileProperty(String propertyId) {
        ReconciliationExecution execution = acquireExecution(propertyId);
        Instant started = Instant.now();
        execution.setRunning(true);
        execution.setLastStartedAt(started);
        execution.setLastStatus(ReconciliationExecutionStatus.RUNNING);
        execution.setLastError(null);
        executionRepository.save(execution);

        try {
            PropertyDto property = propertyWizardClient.getPublishedProperty(propertyId);
            if (property == null || !property.published()) {
                throw new ResourceNotFoundException("Property is not published in Property Wizard");
            }

            List<RoomTypeDto> roomTypes = propertyWizardClient.getRoomTypes(propertyId);
            List<PhysicalRoomDto> physicalRooms = propertyWizardClient.getPhysicalRooms(propertyId);

            Map<Long, Long> totalsByRoomType = physicalRooms.stream()
                    .filter(room -> Objects.equals(room.propertyId(), propertyId))
                    .collect(Collectors.groupingBy(PhysicalRoomDto::roomTypeId, Collectors.counting()));

            LocalDate today = LocalDate.now();
            LocalDate endDateExclusive = today.plusDays(inventoryProperties.getReconciliation().getHorizonDays());

            int rowsCreated = 0;
            int rowsUpdated = 0;
            int rowsUnchanged = 0;

            for (RoomTypeDto roomType : roomTypes) {
                int totalInventory = Math.toIntExact(totalsByRoomType.getOrDefault(roomType.roomTypeId(), 0L));
                List<RoomTypeInventoryDaily> rows = dailyRepository
                        .findByPropertyIdAndRoomTypeIdAndBusinessDateGreaterThanEqualAndBusinessDateLessThanOrderByBusinessDate(
                                propertyId, roomType.roomTypeId(), today, endDateExclusive);

                Map<LocalDate, RoomTypeInventoryDaily> rowByDate = rows.stream()
                        .collect(Collectors.toMap(RoomTypeInventoryDaily::getBusinessDate, row -> row));

                List<RoomTypeInventoryDaily> toSave = new ArrayList<>();
                for (LocalDate date = today; date.isBefore(endDateExclusive); date = date.plusDays(1)) {
                    RoomTypeInventoryDaily row = rowByDate.get(date);
                    if (row == null) {
                        toSave.add(RoomTypeInventoryDaily.builder()
                                .propertyId(propertyId)
                                .roomTypeId(roomType.roomTypeId())
                                .businessDate(date)
                                .totalInventory(totalInventory)
                                .reservedCount(0)
                                .blockedCount(0)
                                .build());
                        rowsCreated++;
                        continue;
                    }

                    if (row.getTotalInventory() == totalInventory) {
                        rowsUnchanged++;
                        continue;
                    }

                    if (totalInventory < row.getReservedCount()) {
                        throw new InventoryConfigurationConflictException(
                                "Room type inventory cannot be reduced below existing reserved inventory. "
                                        + "propertyId=" + propertyId
                                        + " roomTypeId=" + roomType.roomTypeId()
                                        + " date=" + date
                                        + " reserved=" + row.getReservedCount()
                                        + " requestedTotal=" + totalInventory);
                    }

                    row.setTotalInventory(totalInventory);
                    toSave.add(row);
                    rowsUpdated++;
                }

                if (!toSave.isEmpty()) {
                    dailyRepository.saveAll(toSave);
                }
            }

            String summaryMessage = "Reconciliation completed in "
                    + Duration.between(started, Instant.now()).toMillis()
                    + "ms";

            execution.setRunning(false);
            execution.setLastCompletedAt(Instant.now());
            execution.setLastStatus(ReconciliationExecutionStatus.SUCCESS);
            execution.setLastSummary(summaryMessage + ", created=" + rowsCreated + ", updated=" + rowsUpdated + ", unchanged=" + rowsUnchanged);
            executionRepository.save(execution);

            log.info("Reconciliation success propertyId={} roomTypes={} rowsCreated={} rowsUpdated={} rowsUnchanged={} durationMs={}",
                    propertyId, roomTypes.size(), rowsCreated, rowsUpdated, rowsUnchanged,
                    Duration.between(started, Instant.now()).toMillis());

            return new ReconciliationSummaryResponse(
                    propertyId,
                    roomTypes.size(),
                    rowsCreated,
                    rowsUpdated,
                    rowsUnchanged,
                    summaryMessage);
        } catch (RuntimeException ex) {
            execution.setRunning(false);
            execution.setLastCompletedAt(Instant.now());
            execution.setLastStatus(ReconciliationExecutionStatus.FAILED);
            execution.setLastError(ex.getMessage());
            executionRepository.save(execution);
            log.error("Reconciliation failed propertyId={} message={}", propertyId, ex.getMessage(), ex);
            throw ex;
        }
    }

    @Override
    @Transactional
    public ReconciliationStatusResponse getStatus(String propertyId) {
        ReconciliationExecution execution = executionRepository.findById(propertyId)
                .orElseThrow(() -> new ResourceNotFoundException("No reconciliation status found for propertyId=" + propertyId));

        return new ReconciliationStatusResponse(
                execution.getPropertyId(),
                execution.isRunning(),
                execution.getLastStatus(),
                execution.getLastStartedAt(),
                execution.getLastCompletedAt(),
                execution.getLastSummary(),
                execution.getLastError());
    }

    private ReconciliationExecution acquireExecution(String propertyId) {
        ReconciliationExecution execution = executionRepository.findByPropertyId(propertyId)
                .orElseGet(() -> executionRepository.save(ReconciliationExecution.builder()
                        .propertyId(propertyId)
                        .running(false)
                        .version(0L)
                        .build()));

        if (execution.isRunning()) {
            throw new InventoryConfigurationConflictException("Reconciliation is already running for propertyId=" + propertyId);
        }
        return execution;
    }
}

