package com.pms.inventory;

import static org.assertj.core.api.Assertions.assertThat;

import com.pms.inventory.inventory.dto.request.ReserveInventoryRequest;
import com.pms.inventory.inventory.entity.InventoryReservationStatus;
import com.pms.inventory.inventory.entity.RoomTypeInventoryDaily;
import com.pms.inventory.inventory.repository.RoomTypeInventoryDailyRepository;
import com.pms.inventory.inventory.service.InventoryReservationService;
import java.time.LocalDate;
import java.util.List;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;

@SpringBootTest
@Testcontainers
class InventoryIntegrationTest {

    @Container
    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:16-alpine");

    @DynamicPropertySource
    static void configure(DynamicPropertyRegistry registry) {
        registry.add("spring.datasource.url", postgres::getJdbcUrl);
        registry.add("spring.datasource.username", postgres::getUsername);
        registry.add("spring.datasource.password", postgres::getPassword);
        registry.add("spring.flyway.enabled", () -> true);
        registry.add("security.jwt.secret", () -> "pms-inventory-super-secret-key-change-me-2026");
    }

    @Autowired
    private RoomTypeInventoryDailyRepository dailyRepository;

    @Autowired
    private InventoryReservationService reservationService;

    @BeforeEach
    void setUp() {
        dailyRepository.deleteAll();
        LocalDate checkIn = LocalDate.now().plusDays(1);
        List<RoomTypeInventoryDaily> rows = List.of(
                row(checkIn),
                row(checkIn.plusDays(1)),
                row(checkIn.plusDays(2)));
        dailyRepository.saveAll(rows);
    }

    @Test
    void reserveAndReleaseShouldBeIdempotent() {
        LocalDate checkIn = LocalDate.now().plusDays(1);
        ReserveInventoryRequest request = new ReserveInventoryRequest(
                "RES-9001",
                "property-1",
                101L,
                checkIn,
                checkIn.plusDays(3),
                1);

        var firstReserve = reservationService.reserveInventory(request);
        var secondReserve = reservationService.reserveInventory(request);
        var firstRelease = reservationService.releaseInventory("RES-9001");
        var secondRelease = reservationService.releaseInventory("RES-9001");

        assertThat(firstReserve.status()).isEqualTo(InventoryReservationStatus.RESERVED);
        assertThat(secondReserve.idempotent()).isTrue();
        assertThat(firstRelease.status()).isEqualTo(InventoryReservationStatus.RELEASED);
        assertThat(secondRelease.idempotent()).isTrue();
    }

    private RoomTypeInventoryDaily row(LocalDate date) {
        return RoomTypeInventoryDaily.builder()
                .propertyId("property-1")
                .roomTypeId(101L)
                .businessDate(date)
                .totalInventory(3)
                .reservedCount(0)
                .blockedCount(0)
                .build();
    }
}

