    @BeforeEach
    void setUp() {
        service = new InventoryReservationServiceImpl(reservationRepository, dailyRepository);
    }

    @Test
    void reserveInventoryShouldSucceedForAllDates() {
        ReserveInventoryRequest request = new ReserveInventoryRequest("RES-1001", "property-1", 101L,
                LocalDate.now().plusDays(1), LocalDate.now().plusDays(4), 1);

        when(reservationRepository.findByReservationId("RES-1001")).thenReturn(Optional.empty());
        when(dailyRepository.findByPropertyIdAndRoomTypeIdAndBusinessDateGreaterThanEqualAndBusinessDateLessThanOrderByBusinessDate(
                any(), any(), any(), any())).thenReturn(List.of(
                dailyRow(request.checkInDate(), 2, 0, 0),
                dailyRow(request.checkInDate().plusDays(1), 2, 0, 0),
                dailyRow(request.checkInDate().plusDays(2), 2, 0, 0)));
        when(reservationRepository.save(any())).thenAnswer(invocation -> invocation.getArgument(0));

        InventoryReservationResponse response = service.reserveInventory(request);

        assertEquals(InventoryReservationStatus.RESERVED, response.status());
        assertEquals("RES-1001", response.reservationId());
        verify(dailyRepository).saveAll(any());
    }

    @Test
    void reserveInventoryShouldFailWhenAnyDateUnavailable() {
        ReserveInventoryRequest request = new ReserveInventoryRequest("RES-2001", "property-1", 101L,
                LocalDate.now().plusDays(1), LocalDate.now().plusDays(4), 2);

        when(reservationRepository.findByReservationId("RES-2001")).thenReturn(Optional.empty());
        when(dailyRepository.findByPropertyIdAndRoomTypeIdAndBusinessDateGreaterThanEqualAndBusinessDateLessThanOrderByBusinessDate(
                any(), any(), any(), any())).thenReturn(List.of(
                dailyRow(request.checkInDate(), 3, 1, 0),
                dailyRow(request.checkInDate().plusDays(1), 3, 2, 0),
                dailyRow(request.checkInDate().plusDays(2), 3, 2, 0)));

        assertThrows(InventoryConflictException.class, () -> service.reserveInventory(request));
    }

    @Test
    void reserveInventoryShouldReturnIdempotentWhenReservationAlreadyExists() {
        ReserveInventoryRequest request = new ReserveInventoryRequest("RES-3001", "property-1", 101L,
                LocalDate.now().plusDays(1), LocalDate.now().plusDays(3), 1);

        InventoryReservation existing = InventoryReservation.builder()
                .reservationId("RES-3001")
                .propertyId("property-1")
                .roomTypeId(101L)
                .checkInDate(request.checkInDate())
                .checkOutDate(request.checkOutDate())
                .quantity(1)
                .status(InventoryReservationStatus.RESERVED)
                .build();

        when(reservationRepository.findByReservationId("RES-3001")).thenReturn(Optional.of(existing));

        InventoryReservationResponse response = service.reserveInventory(request);

        assertEquals(true, response.idempotent());
        assertEquals(InventoryReservationStatus.RESERVED, response.status());
    }

    private RoomTypeInventoryDaily dailyRow(LocalDate date, int total, int reserved, int blocked) {
        return RoomTypeInventoryDaily.builder()
                .propertyId("property-1")
                .roomTypeId(101L)
                .businessDate(date)
                .totalInventory(total)
                .reservedCount(reserved)
                .blockedCount(blocked)
                .build();
    }
}

package com.pms.inventory.reconciliation.service;

import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

import com.pms.inventory.common.config.InventoryProperties;
import com.pms.inventory.common.exception.InventoryConfigurationConflictException;
import com.pms.inventory.integration.propertywizard.PropertyWizardClient;
import com.pms.inventory.integration.propertywizard.dto.PhysicalRoomDto;
import com.pms.inventory.integration.propertywizard.dto.PropertyDto;
import com.pms.inventory.integration.propertywizard.dto.RoomTypeDto;
import com.pms.inventory.inventory.entity.RoomTypeInventoryDaily;
import com.pms.inventory.inventory.repository.RoomTypeInventoryDailyRepository;
import com.pms.inventory.reconciliation.entity.ReconciliationExecution;
import com.pms.inventory.reconciliation.repository.ReconciliationExecutionRepository;
import com.pms.inventory.reconciliation.service.impl.InventoryReconciliationServiceImpl;
import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

@ExtendWith(MockitoExtension.class)
class InventoryReconciliationServiceImplTest {

    @Mock
    private PropertyWizardClient propertyWizardClient;
    @Mock
    private RoomTypeInventoryDailyRepository dailyRepository;
    @Mock
    private ReconciliationExecutionRepository executionRepository;

    private InventoryReconciliationServiceImpl service;

    @BeforeEach
    void setUp() {
        InventoryProperties properties = new InventoryProperties();
        properties.getReconciliation().setHorizonDays(2);
        service = new InventoryReconciliationServiceImpl(propertyWizardClient, dailyRepository, executionRepository, properties);
    }

    @Test
    void reconcileShouldThrowConflictWhenTotalLessThanReserved() {
        when(executionRepository.findByPropertyId("property-1"))
                .thenReturn(Optional.of(ReconciliationExecution.builder().propertyId("property-1").running(false).build()));
        when(executionRepository.save(any())).thenAnswer(invocation -> invocation.getArgument(0));

        when(propertyWizardClient.getPublishedProperty("property-1")).thenReturn(new PropertyDto("property-1", true));
        when(propertyWizardClient.getRoomTypes("property-1")).thenReturn(List.of(new RoomTypeDto(101L, "property-1")));
        when(propertyWizardClient.getPhysicalRooms("property-1")).thenReturn(List.of(
                new PhysicalRoomDto(1L, 101L, "property-1")));

        RoomTypeInventoryDaily existing = RoomTypeInventoryDaily.builder()
                .propertyId("property-1")
                .roomTypeId(101L)
                .businessDate(LocalDate.now())
                .totalInventory(3)
                .reservedCount(2)
                .blockedCount(0)
                .build();

        when(dailyRepository.findByPropertyIdAndRoomTypeIdAndBusinessDateGreaterThanEqualAndBusinessDateLessThanOrderByBusinessDate(
                any(), any(), any(), any())).thenReturn(List.of(existing));

        assertThrows(InventoryConfigurationConflictException.class, () -> service.reconcileProperty("property-1"));
    }
}
